-- Generated by gen_special_pages.py from special-fields.json - do not
-- hand-edit, re-run the generator.
--
-- A factory function, not a flat module table: the dedicated GET routes'
-- query schemas need idx_common (mediawiki.lua's own hand-written common-
-- fields table), which isn't visible inside this separately-required file -
-- so mediawiki.lua does
-- `local special_pages = require("waf.apps.mediawiki.special_pages")(idx_common)`
-- instead of a plain require().
return function(idx_common)
local T = require "waf.types"

-- Shallow-merges one or more {key=validator} tables into a new table; later
-- tables' keys win on conflict.
local function merge(...)
  local out = {}
  for _, t in ipairs({...}) do
    for k, v in pairs(t) do out[k] = v end
  end
  return out
end

